+package com.example;
+
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Application-scoped, in-memory storage.  It intentionally outlives individual
+ * view instances, while keeping the example free from persistence setup.
+ */
+@Service
+public class ContactMessageStore {
+
+    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    public List<ContactMessage> newestFirst() {
+        return Collections.unmodifiableList(new ArrayList<>(messages));
+    }
+}
